【図解】移送取扱所に課される義務
　義務の種類｜倍数による要否
　予防規程の作成｜倍数にかかわらず必要
　定期点検の実施｜倍数にかかわらず必要
　危険物保安監督者の選任｜倍数にかかわらず必要
