　第2類｜硫黄、硫化りん、赤りん、引火点0度以上の引火性固体
　第4類｜引火点0度以上の第1石油類、アルコール類
　第4類｜第2石油類、第3石油類、第4石油類、動植物油類
　貯蔵できないもの｜特殊引火物、ガソリン、第1類、第3類、第5類、第6類
