【図解】販売取扱所の基準
　項目｜基準
　第1種の倍数｜15倍以下
　第2種の倍数｜15倍を超え40倍以下
　設置階｜建築物の1階
　危険物の配合室の床面積｜6平方メートル以上10平方メートル以下
