    correctKey: 'A',
    explanation: `液体の危険物を貯蔵し又は取り扱うタンクを設置し又は変更する場合、タンクが完成した段階で市町村長等が行う完成検査前検査を受けなければならない。この検査は工事の工程ごとに行われるもので、圧力タンクについては最大常用圧力の1.5倍の圧力で行う水圧検査、圧力タンク以外のタンクについては水張検査が実施される。地下タンクや二重殻タンクについては基礎地盤検査や溶接部検査が行われる場合もある。完成検査前検査に合格しなければ工事を進めることができない。

【図解】タンクの検査の種類
　タンクの区分｜検査の種類
　圧力タンク｜水圧検査（最大常用圧力の1.5倍）
　圧力タンク以外のタンク｜水張検査
　特定屋外貯蔵タンク｜基礎地盤検査、溶接部検査等
　⚠ 完成検査前検査は工事の途中、完成検査は工事完了後`,
