【図解】危険物保安監督者の選任義務
　施設｜選任義務
　製造所｜倍数に関係なく必要
　屋外タンク貯蔵所｜倍数に関係なく必要
　給油取扱所｜倍数に関係なく必要
　移送取扱所｜倍数に関係なく必要
　移動タンク貯蔵所｜不要
