　種類｜対象｜例
　行政処分（施設）｜製造所等｜許可取消し、使用停止命令
　行政処分（人）｜危険物取扱者｜免状の返納命令
　罰則｜違反した者、法人｜拘禁刑、罰金、両罰規定
